// MT2009_PLUS_PICKUP_RULES_V1 (server-patches/pickuprules, Autor: Vekirion): the detailed filter
// of a kind (the owner, 13 October: "a complex pickup filter ... the amount of
// bonuses, what those bonuses are and of what value"; and the same day: the
// Ctrl+Z window replaced - a left click takes a kind or not, a right click
// opens its detailed filter: chosen items, refine, level and bonuses).
// The client (uipickupfilter.py / uipickupfilterrules.py) sends the rules as
//   /pickup_rules begin
//   /pickup_rules add <kinds> <min normal> <min rare> <+min> <+max> <lv min> <lv max> <mode> <need> [<type>:<value>:<slots>[:<op>] ...] [v<vnum> ...] [o<n>]
//   /pickup_rules items <vnum> ...      (more items for the last rule added)
//   /pickup_rules end                   -> "PickupRulesAck <rules kept>"
//   /pickup_rules clear                 -> "PickupRulesAck 0"
// The set is swapped in whole at "end", so a half-sent set never decides.
// A rule is for some kinds (the filter's 13 bits) and asks for:
//  - one of its items, when it names any - a refinable item (weapon, armour,
//    belt) by its line, the vnum of its +0 (vnum - vnum % 10), anything else
//    by its own vnum;
//  - refine from <+min> to <+max> (weapon, armour and belt; 0..15 = any);
//  - a wear level from <lv min> to <lv max> (<lv max> 0 = no upper bound);
//  - at least <min normal> of the five bonuses and <min rare> of the 6th/7th;
//  - and its conditions - a bonus <type> (the POINT_* number the item's slots
//    hold) of at least <value> in the normal slots (1), the rare ones (2) or
//    any (0) - all (mode 0), any one (1) or at least <need> (2) of them.
//    MT2009_PLUS_PICKUP_COND_ABSENT_V1 (the owner, 14 October): with <op> 1
//    the condition is "no bonus <type> there, or it above <value>" - met by
//    an item without the bonus, and by one with it only when its value is
//    greater than <value>. No <op> (or 0): "at least <value>", as before.
//    MT2009_PLUS_PICKUP_OTHER_BONUSES_V1 (the owner, 15 October): with o<n>
//    the rule also takes an item with at least <n> bonuses in slots 1-5 of
//    types none of its conditions names, whatever the conditions say (an
//    older server skips the token).
// A kind the filter takes is decided by its switched-on rules when it has any
// (ANY rule matching takes the item); with none, everything of it is taken
// (or the plain "Min. bonusow" count of MT2009_PLUS_PICKUP_BONUS_FILTER_V1,
// which an older client may still send). Kept by player id in memory, as the
// filter; the client sends it after every login and warp.
// "/pickup_items <req> <kind> <text>" finds items of a kind by name for the
// window's item search: "PickupItemsList <req> <vnum>,<vnum>,..." (lines, as
// above) or "PickupItemsList <req> -".
enum
{
	MT2009_PLUS_PICKUP_RULE_MAX = 40,
	MT2009_PLUS_PICKUP_RULE_COND_MAX = 6,
	MT2009_PLUS_PICKUP_RULE_ITEM_MAX = 16,
	MT2009_PLUS_PICKUP_RULE_REFINE_MAX = 15,
	MT2009_PLUS_PICKUP_RULE_LEVEL_MAX = 250,
	MT2009_PLUS_PICKUP_SEARCH_MAX = 36,
};

enum
{
	MT2009_PLUS_PICKUP_RULE_ALL = 0,
	MT2009_PLUS_PICKUP_RULE_ANY = 1,
	MT2009_PLUS_PICKUP_RULE_AT_LEAST = 2,
};

enum
{
	MT2009_PLUS_PICKUP_SLOTS_ANY = 0,
	MT2009_PLUS_PICKUP_SLOTS_NORMAL = 1,
	MT2009_PLUS_PICKUP_SLOTS_RARE = 2,
};

static const DWORD MT2009_PLUS_PICKUP_ALL_KINDS = 0x1FFF;

enum
{
	MT2009_PLUS_PICKUP_COND_AT_LEAST = 0,
	MT2009_PLUS_PICKUP_COND_ABSENT_OR_ABOVE = 1,	// MT2009_PLUS_PICKUP_COND_ABSENT_V1
};

struct SMt2009PlusPickupCond
{
	BYTE type;
	int minValue;
	BYTE slots;
	BYTE op;	// MT2009_PLUS_PICKUP_COND_ABSENT_V1
};

struct SMt2009PlusPickupRule
{
	DWORD kinds;
	int minNormal;
	int minRare;
	int refineMin;
	int refineMax;
	int levelMin;
	int levelMax;
	int mode;
	int need;
	std::vector<SMt2009PlusPickupCond> conds;
	std::vector<DWORD> lines;
	int otherMin;	// MT2009_PLUS_PICKUP_OTHER_BONUSES_V1: 0 = off

	SMt2009PlusPickupRule() : kinds(0), minNormal(0), minRare(0), refineMin(0), refineMax(0),
		levelMin(0), levelMax(0), mode(0), need(1), otherMin(0) {}
};

typedef std::vector<SMt2009PlusPickupRule> TMt2009PlusPickupRules;
static std::map<DWORD, TMt2009PlusPickupRules> s_mapMt2009PlusPickupRules;
static std::map<DWORD, TMt2009PlusPickupRules> s_mapMt2009PlusPickupRulesPending;

static bool Mt2009PlusPickupRefinable(BYTE type)
{
	return type == ITEM_WEAPON || type == ITEM_ARMOR || type == ITEM_BELT;
}

// The item's line: a refinable item's +0 vnum, anything else's own.
static DWORD Mt2009PlusPickupLine(DWORD vnum, BYTE type)
{
	return Mt2009PlusPickupRefinable(type) ? vnum - vnum % 10 : vnum;
}

static bool Mt2009PlusPickupCondMet(LPITEM item, const SMt2009PlusPickupCond& cond)
{
	const int from = cond.slots == MT2009_PLUS_PICKUP_SLOTS_RARE ? ITEM_ATTRIBUTE_RARE_START : ITEM_ATTRIBUTE_NORM_START;
	const int to = cond.slots == MT2009_PLUS_PICKUP_SLOTS_NORMAL ? ITEM_ATTRIBUTE_NORM_END : ITEM_ATTRIBUTE_RARE_END;
	if (cond.op == MT2009_PLUS_PICKUP_COND_ABSENT_OR_ABOVE)
	{
		// MT2009_PLUS_PICKUP_COND_ABSENT_V1: no such bonus, or it above the value
		bool found = false;
		for (int i = from; i < to; ++i)
		{
			if (item->GetAttributeType(i) != cond.type)
				continue;
			found = true;
			if (item->GetAttributeValue(i) > cond.minValue)
				return true;
		}
		return !found;
	}
	for (int i = from; i < to; ++i)
	{
		if (item->GetAttributeType(i) == cond.type && item->GetAttributeValue(i) >= cond.minValue)
			return true;
	}
	return false;
}

static bool Mt2009PlusPickupRuleMatches(LPITEM item, const SMt2009PlusPickupRule& rule)
{
	if (!rule.lines.empty())
	{
		const DWORD line = Mt2009PlusPickupLine(item->GetVnum(), item->GetType());
		if (std::find(rule.lines.begin(), rule.lines.end(), line) == rule.lines.end())
			return false;
	}
	if (Mt2009PlusPickupRefinable(item->GetType()) &&
		(rule.refineMin > 0 || rule.refineMax < MT2009_PLUS_PICKUP_RULE_REFINE_MAX))
	{
		const int refine = item->GetRefineLevel();
		if (refine < rule.refineMin || refine > rule.refineMax)
			return false;
	}
	if (rule.levelMin > 0 || rule.levelMax > 0)
	{
		const int level = item->GetLevelLimit();
		if (level < rule.levelMin || (rule.levelMax > 0 && level > rule.levelMax))
			return false;
	}
	if (item->GetAttributeCount() < rule.minNormal)
		return false;
	if (item->GetRareAttrCount() < rule.minRare)
		return false;
	if (rule.conds.empty())
		return true;

	// MT2009_PLUS_PICKUP_OTHER_BONUSES_V1: or at least otherMin bonuses (slots
	// 1-5) of types none of the conditions names
	if (rule.otherMin > 0)
	{
		int others = 0;
		for (int i = ITEM_ATTRIBUTE_NORM_START; i < ITEM_ATTRIBUTE_NORM_END; ++i)
		{
			const BYTE type = item->GetAttributeType(i);
			if (!type)
				continue;
			bool named = false;
			for (size_t c = 0; c < rule.conds.size() && !named; ++c)
				named = rule.conds[c].type == type;
			if (!named)
				++others;
		}
		if (others >= rule.otherMin)
			return true;
	}

	int met = 0;
	for (size_t i = 0; i < rule.conds.size(); ++i)
	{
		if (Mt2009PlusPickupCondMet(item, rule.conds[i]))
			++met;
	}

	switch (rule.mode)
	{
		case MT2009_PLUS_PICKUP_RULE_ANY:
			return met >= 1;
		case MT2009_PLUS_PICKUP_RULE_AT_LEAST:
			return met >= MIN(rule.need, (int) rule.conds.size());
		default:
			return met == (int) rule.conds.size();
	}
}

// -1: no rule of the character is for this kind; otherwise 1 when one of
// the rules for it matches, 0 when none does.
static int Mt2009PlusPickupRulesDecide(DWORD pid, DWORD kind, LPITEM item)
{
	std::map<DWORD, TMt2009PlusPickupRules>::const_iterator it = s_mapMt2009PlusPickupRules.find(pid);
	if (it == s_mapMt2009PlusPickupRules.end())
		return -1;
	bool named = false;
	for (size_t i = 0; i < it->second.size(); ++i)
	{
		const SMt2009PlusPickupRule& rule = it->second[i];
		if (!(rule.kinds & kind))
			continue;
		named = true;
		if (Mt2009PlusPickupRuleMatches(item, rule))
			return 1;
	}
	return named ? 0 : -1;
}

static int Mt2009PlusPickupRuleNumber(const char* text, int low, int high, int fallback)
{
	if (!text || !*text)
		return fallback;
	int value = fallback;
	str_to_number(value, text);
	return MINMAX(low, value, high);
}

static void Mt2009PlusPickupRuleAddLine(SMt2009PlusPickupRule& rule, const char* text)
{
	unsigned long vnum = 0;
	str_to_number(vnum, text);
	if (!vnum || rule.lines.size() >= MT2009_PLUS_PICKUP_RULE_ITEM_MAX)
		return;
	if (std::find(rule.lines.begin(), rule.lines.end(), (DWORD) vnum) == rule.lines.end())
		rule.lines.push_back((DWORD) vnum);
}

// "/pickup_rules ..." (cmd_general.cpp, do_pickup_rules). Returns the number
// of rules for the "PickupRulesAck" answer, or -1 when nothing is answered
// (begin, add, items).
int Mt2009PlusPickupRulesCommand(LPCHARACTER ch, const char* argument)
{
	if (!ch || !ch->IsPC())
		return -1;
	const DWORD pid = ch->GetPlayerID();
	char word[64];
	const char* rest = one_argument(argument, word, sizeof(word));

	if (!strcmp(word, "begin"))
	{
		s_mapMt2009PlusPickupRulesPending[pid].clear();
		return -1;
	}
	if (!strcmp(word, "clear"))
	{
		s_mapMt2009PlusPickupRulesPending.erase(pid);
		s_mapMt2009PlusPickupRules.erase(pid);
		return 0;
	}
	if (!strcmp(word, "end"))
	{
		std::map<DWORD, TMt2009PlusPickupRules>::iterator pending = s_mapMt2009PlusPickupRulesPending.find(pid);
		if (pending == s_mapMt2009PlusPickupRulesPending.end())
		{
			std::map<DWORD, TMt2009PlusPickupRules>::const_iterator kept = s_mapMt2009PlusPickupRules.find(pid);
			return kept == s_mapMt2009PlusPickupRules.end() ? 0 : (int) kept->second.size();
		}
		const int count = (int) pending->second.size();
		if (count)
			s_mapMt2009PlusPickupRules[pid].swap(pending->second);
		else
			s_mapMt2009PlusPickupRules.erase(pid);
		s_mapMt2009PlusPickupRulesPending.erase(pending);
		return count;
	}

	std::map<DWORD, TMt2009PlusPickupRules>::iterator pending = s_mapMt2009PlusPickupRulesPending.find(pid);
	if (pending == s_mapMt2009PlusPickupRulesPending.end())
		return -1;

	char token[48];
	if (!strcmp(word, "items"))
	{
		if (pending->second.empty())
			return -1;
		SMt2009PlusPickupRule& rule = pending->second.back();
		for (;;)
		{
			rest = one_argument(rest, token, sizeof(token));
			if (!*token)
				break;
			Mt2009PlusPickupRuleAddLine(rule, token[0] == 'v' ? token + 1 : token);
		}
		return -1;
	}
	if (strcmp(word, "add") || pending->second.size() >= MT2009_PLUS_PICKUP_RULE_MAX)
		return -1;

	char fields[9][16];
	for (int i = 0; i < 9; ++i)
		rest = one_argument(rest, fields[i], sizeof(fields[i]));

	SMt2009PlusPickupRule rule;
	unsigned long kinds = 0;
	str_to_number(kinds, fields[0]);
	rule.kinds = (DWORD) kinds & MT2009_PLUS_PICKUP_ALL_KINDS;
	rule.minNormal = Mt2009PlusPickupRuleNumber(fields[1], 0, ITEM_ATTRIBUTE_NORM_NUM, 0);
	rule.minRare = Mt2009PlusPickupRuleNumber(fields[2], 0, ITEM_ATTRIBUTE_RARE_NUM, 0);
	rule.refineMin = Mt2009PlusPickupRuleNumber(fields[3], 0, MT2009_PLUS_PICKUP_RULE_REFINE_MAX, 0);
	rule.refineMax = Mt2009PlusPickupRuleNumber(fields[4], 0, MT2009_PLUS_PICKUP_RULE_REFINE_MAX, MT2009_PLUS_PICKUP_RULE_REFINE_MAX);
	rule.levelMin = Mt2009PlusPickupRuleNumber(fields[5], 0, MT2009_PLUS_PICKUP_RULE_LEVEL_MAX, 0);
	rule.levelMax = Mt2009PlusPickupRuleNumber(fields[6], 0, MT2009_PLUS_PICKUP_RULE_LEVEL_MAX, 0);
	rule.mode = Mt2009PlusPickupRuleNumber(fields[7], MT2009_PLUS_PICKUP_RULE_ALL, MT2009_PLUS_PICKUP_RULE_AT_LEAST, MT2009_PLUS_PICKUP_RULE_ALL);
	rule.need = Mt2009PlusPickupRuleNumber(fields[8], 1, MT2009_PLUS_PICKUP_RULE_COND_MAX, 1);
	if (!rule.kinds)
		return -1;
	if (rule.refineMax < rule.refineMin)
		std::swap(rule.refineMin, rule.refineMax);
	if (rule.levelMax > 0 && rule.levelMax < rule.levelMin)
		std::swap(rule.levelMin, rule.levelMax);

	for (;;)
	{
		rest = one_argument(rest, token, sizeof(token));
		if (!*token)
			break;
		if (token[0] == 'v')
		{
			Mt2009PlusPickupRuleAddLine(rule, token + 1);
			continue;
		}
		if (token[0] == 'o')	// MT2009_PLUS_PICKUP_OTHER_BONUSES_V1
		{
			rule.otherMin = Mt2009PlusPickupRuleNumber(token + 1, 0, ITEM_ATTRIBUTE_NORM_NUM, 0);
			continue;
		}
		if (rule.conds.size() >= MT2009_PLUS_PICKUP_RULE_COND_MAX)
			continue;
		int type = 0, value = 0, slots = 0, op = 0;
		if (sscanf(token, "%d:%d:%d:%d", &type, &value, &slots, &op) < 2 || type <= 0 || type > 255)
			continue;
		SMt2009PlusPickupCond cond;
		cond.type = (BYTE) type;
		cond.minValue = MINMAX(0, value, 32767);
		cond.slots = (BYTE) MINMAX((int) MT2009_PLUS_PICKUP_SLOTS_ANY, slots, (int) MT2009_PLUS_PICKUP_SLOTS_RARE);
		cond.op = (BYTE) MINMAX((int) MT2009_PLUS_PICKUP_COND_AT_LEAST, op, (int) MT2009_PLUS_PICKUP_COND_ABSENT_OR_ABOVE);	// MT2009_PLUS_PICKUP_COND_ABSENT_V1
		rule.conds.push_back(cond);
	}
	pending->second.push_back(rule);
	return -1;
}

// "/pickup_items <req> <kind> <text>" (cmd_general.cpp, do_pickup_items): the
// lines of the kind whose name holds the text, at most
// MT2009_PLUS_PICKUP_SEARCH_MAX, as one "PickupItemsList" answer.
void Mt2009PlusPickupItemsCommand(LPCHARACTER ch, const char* argument)
{
	if (!ch || !ch->IsPC())
		return;
	static std::map<DWORD, DWORD> s_nextSearch;
	const DWORD now = get_dword_time();
	DWORD& next = s_nextSearch[ch->GetPlayerID()];
	if (now < next)
		return;
	next = now + 250;

	char req[16], kindText[16];
	const char* rest = one_argument(argument, req, sizeof(req));
	rest = one_argument(rest, kindText, sizeof(kindText));
	unsigned long kind = 0;
	str_to_number(kind, kindText);
	kind &= MT2009_PLUS_PICKUP_ALL_KINDS;
	while (*rest == ' ')
		++rest;
	std::string query = StringToLower(rest, strnlen(rest, 64));
	while (!query.empty() && query[query.size() - 1] == ' ')
		query.erase(query.size() - 1);

	std::string answer;
	if (kind && query.size() >= 2)
	{
		std::vector<DWORD> found;
		const std::vector<TItemTable>& table = ITEM_MANAGER::instance().GetTable();
		for (size_t i = 0; i < table.size() && found.size() < MT2009_PLUS_PICKUP_SEARCH_MAX; ++i)
		{
			const TItemTable& proto = table[i];
			if (proto.bType == ITEM_ELK || !(Mt2009PlusPickupKindOf(proto.bType, proto.bSubType) & kind))
				continue;
			const std::string name = StringToLower(proto.szLocaleName, strnlen(proto.szLocaleName, ITEM_NAME_MAX_LEN));
			if (name.find(query) == std::string::npos)
				continue;
			const DWORD line = Mt2009PlusPickupLine(proto.dwVnum, proto.bType);
			if (std::find(found.begin(), found.end(), line) == found.end())
				found.push_back(line);
		}
		for (size_t i = 0; i < found.size(); ++i)
		{
			char buf[16];
			snprintf(buf, sizeof(buf), i ? ",%u" : "%u", (unsigned int) found[i]);
			answer += buf;
		}
	}
	ch->ChatPacket(CHAT_TYPE_COMMAND, "PickupItemsList %s %s", *req ? req : "0", answer.empty() ? "-" : answer.c_str());
}

bool Mt2009PlusPickupFilterAllows(LPCHARACTER ch, LPITEM item)
{
